# Hybrid classifier — Rule-based primary + TF-IDF fallback
# 策略：Rule-based 为主（chat/summarization 强项），TF-IDF 兜底（reasoning/coding/format 强项）
# 1. summarization 关键词命中 → 直接 summarization
# 2. Rule-based 有规则命中 → 用 Rule-based
# 3. Rule-based 无命中 → TF-IDF 高置信度采纳
# 4. TF-IDF 低置信度 → 默认 chat
import logging
import re as _re
import math as _math
from collections import Counter as _Counter
from jiuwenswarm.agents.harness.common.rails.model_routing.classifier import _lookup_score

_log = logging.getLogger('ModelRouting')

# ── Build Rule engine (cached) ──
_rules = _EXTRAS.get('_compiled_rules')
if _rules is None:
    compiled = []
    for rule in _EXTRAS.get('rules', []):
        try:
            pat = _re.compile(rule['pattern'])
            compiled.append((pat, rule.get('targets', [])))
        except _re.error as e:
            _log.warning('rule %s compile failed: %s', rule.get('id', '?'), e)
    _rules = compiled
    _EXTRAS['_compiled_rules'] = _rules
    _log.info('hybrid: rule engine compiled: %d rules', len(_rules))

# ── Build TF-IDF engine (cached) ──
_engine = _EXTRAS.get('_tfidf_engine')
if _engine is None:
    def _tokenize(text):
        tokens = []
        for word in _re.findall(r'[a-zA-Z]{2,}', text):
            tokens.append(word.lower())
        for num in _re.findall(r'\d+', text):
            tokens.append(num)
        for seq in _re.findall(r'[一-鿿㐀-䶿]+', text):
            if len(seq) >= 2:
                tokens.append(seq)
            for ch in seq:
                tokens.append(ch)
        return tokens

    def _sparse_cosine(v1, v2):
        shared = set(v1) & set(v2)
        if not shared:
            return 0.0
        dot = sum(v1[t] * v2[t] for t in shared)
        norm1 = _math.sqrt(sum(v ** 2 for v in v1.values()))
        norm2 = _math.sqrt(sum(v ** 2 for v in v2.values()))
        if norm1 == 0 or norm2 == 0:
            return 0.0
        return dot / (norm1 * norm2)

    cat_utterances = _EXTRAS.get('category_utterances', {})
    all_docs = []
    cat_token_lists = {}
    for cat, utterances in cat_utterances.items():
        cat_token_lists[cat] = [_tokenize(u) for u in utterances]
        all_docs.extend(cat_token_lists[cat])

    N = len(all_docs)
    df = _Counter()
    for doc_tokens in all_docs:
        for t in set(doc_tokens):
            df[t] += 1
    idf = {t: _math.log((N + 1) / (count + 1)) for t, count in df.items()}

    cat_centroids = {}
    for cat, token_lists in cat_token_lists.items():
        term_freq = _Counter()
        for tokens in token_lists:
            term_freq.update(tokens)
        n_docs = len(token_lists)
        centroid = {t: (term_freq[t] / n_docs) * idf.get(t, 0) for t in term_freq}
        cat_centroids[cat] = centroid

    _engine = (idf, cat_centroids)
    _EXTRAS['_tfidf_engine'] = _engine
    _log.info('hybrid: TF-IDF engine built: %d categories, %d IDF terms', len(cat_centroids), len(idf))

_idf, _cat_centroids = _engine

# ── Summarization 专项关键词 ──
_SUMM_PAT = _re.compile(
    r"(?i)(summar|tldr|condense|compress|extract.*(key|main|point|idea)"
    r"|overview|takeaway|gist|abstract|brief.*(overview|summary|description)"
    r"|总结|摘要|概括|提炼|概述|要点)",
)

# ── TF-IDF helper ──
def _tfidf_classify(prompt_text):
    tokens = []
    for word in _re.findall(r'[a-zA-Z]{2,}', prompt_text):
        tokens.append(word.lower())
    for num in _re.findall(r'\d+', prompt_text):
        tokens.append(num)
    for seq in _re.findall(r'[一-鿿㐀-䶿]+', prompt_text):
        if len(seq) >= 2:
            tokens.append(seq)
        for ch in seq:
            tokens.append(ch)
    query_tf = _Counter(tokens)
    query_vec = {t: query_tf[t] * _idf[t] for t in query_tf if t in _idf}

    scores = {}
    shared_keys = set(query_vec) & set(_cat_centroids)
    for cat, centroid in _cat_centroids.items():
        shared = set(query_vec) & set(centroid)
        if not shared:
            scores[cat] = 0.0
            continue
        dot = sum(query_vec[t] * centroid[t] for t in shared)
        norm1 = _math.sqrt(sum(v ** 2 for v in query_vec.values()))
        norm2 = _math.sqrt(sum(v ** 2 for v in centroid.values()))
        if norm1 == 0 or norm2 == 0:
            scores[cat] = 0.0
        else:
            scores[cat] = dot / (norm1 * norm2)

    max_score = max(scores.values()) if scores else 0
    category = max(scores, key=scores.get) if scores else 'chat'
    return category, max_score

# ── Classify ──
# 1. Rule-based
category_scores = {c: 0 for c in _CATEGORIES}
difficulty_scores = {d: 0 for d in _DIFFICULTIES}

for pat, targets in _rules:
    if pat.search(prompt_text):
        for t in targets:
            ttype = t.get('type', '')
            tname = t.get('name', '')
            tscore = t.get('score', 0)
            if ttype == 'category':
                category_scores[tname] += tscore
            elif ttype == 'difficulty':
                difficulty_scores[tname] += tscore

# Length signal
try:
    from openjiuwen.core.context_engine import TiktokenCounter
    _tok = int(TiktokenCounter().count(prompt_text))
except Exception:
    _tok = max(1, len(prompt_text) // 4)

_ls = _EXTRAS.get('length_signal', {})
_easy_t = _ls.get('easy_threshold', 20)
_medium_t = _ls.get('medium_threshold', 80)
if _tok > _medium_t:
    difficulty_scores['hard'] += 1
elif _tok > _easy_t:
    difficulty_scores['medium'] += 1

rule_has_hit = any(v > 0 for v in category_scores.values())
if rule_has_hit:
    rule_category = max(category_scores, key=category_scores.get)
else:
    rule_category = _EXTRAS.get('defaults', {}).get('no_hit_category', 'chat')

if all(v == 0 for v in difficulty_scores.values()):
    if _tok > _medium_t:
        difficulty = 'hard'
    elif _tok > _easy_t:
        difficulty = 'medium'
    else:
        difficulty = 'easy'
else:
    difficulty = max(difficulty_scores, key=difficulty_scores.get)

# 2. Hybrid decision
# 策略：
#   - summarization 关键词 → summarization
#   - rule 有命中 → 用 rule（chat/summarization 强项）
#   - rule 无命中 → TF-IDF：
#     * reasoning/coding/format 需高置信度（>= 0.15）才采纳
#     * chat 中等置信度（>= 0.08）采纳
#     * 低置信度 → 默认 chat
_TFIDF_HIGH_CONF = 0.05
_TFIDF_CHAT_CONF = 0.03

if _SUMM_PAT.search(prompt_text):
    category = 'summarization'
elif rule_has_hit:
    category = rule_category
else:
    tfidf_category, tfidf_conf = _tfidf_classify(prompt_text)
    if tfidf_category in ('reasoning', 'coding', 'format') and tfidf_conf >= _TFIDF_HIGH_CONF:
        category = tfidf_category
    elif tfidf_category == 'chat' and tfidf_conf >= _TFIDF_CHAT_CONF:
        category = 'chat'
    else:
        category = 'chat'  # TF-IDF 低置信度 → 默认 chat

score = _lookup_score(category, difficulty, _SCORE_TABLE, _DEFAULT_SCORE)

_log.debug('hybrid classifier: %s/%s score=%d (rule_hit=%s rule_cat=%s tfidf=%s/%.3f)',
           category, difficulty, score, rule_has_hit, rule_category,
           *_tfidf_classify(prompt_text) if not rule_has_hit else ('skipped', 0))

return score, category, difficulty

